import{_ as e,o as l,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-10-19","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-10-19","date":"2021-10-19T00:00:00.000Z","updated":"2021-10-20T00:00:00.000Z","tags":["Ceph","分布式存储","Orchestrator","NFS","CLI","Rook","ELSO"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-10-19.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-10-19.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-10-19.md"};function p(s,t,a,_,n,c){return l(),o("div",null,[...t[0]||(t[0]=[r("<p>Ceph Orchestrator 会议于2021年10月19日举行，主要讨论了以下议题：</p><ol><li><p><strong>NFS功能缺失</strong>：</p><ul><li>讨论了在Ceph中NFS LGW导出功能在self-ansible支持中的缺失，特别是导出单个桶和与单个用户关联的一组桶的能力。</li><li>确认当前Ceph的NFS模块仅支持在桶级别导出，且用户总是桶的所有者。</li><li>提议通过增加功能，允许通过用户名创建导出，以便用户可以导出其所有的桶。</li></ul></li><li><p><strong>CLI命令调整</strong>：</p><ul><li>讨论了NFS导出创建命令的参数顺序问题，建议调整以提高直观性。</li><li>决定即使可能破坏向后兼容性，也要改进CLI命令，确保用户使用命名参数而非依赖顺序。</li></ul></li><li><p><strong>Rook支持讨论</strong>：</p><ul><li>询问了Rook是否支持类似NFS LGW用户的导出功能，确认Rook支持定义NFS服务器，但导出管理不涉及。</li></ul></li><li><p><strong>ELSO项目进展</strong>：</p><ul><li>讨论了ELSO项目的进展，特别是与Topol VM和Top LVM Operator的集成。</li><li>确认Top LVM项目社区活跃，但Topol VM Operator社区不理想，可能需要重新设计或创建新的Operator。</li><li>计划与Topol VM Operator团队进行会议，讨论可能的贡献和必要的更改。</li></ul></li></ol><p>会议决定：</p><ul><li>改进NFS导出功能的CLI命令，增加通过用户名导出的能力。</li><li>确保用户在使用CLI时使用命名参数，以适应可能的命令调整。</li><li>安排与Topol VM Operator团队的会议，讨论项目贡献和设计更改。</li></ul><p>后续行动计划：</p><ul><li>实施 NFS 导出功能的改进，包括 CLI 命令的调整。</li><li>跟进与 Topol VM Operator 团队的会议，确定项目贡献和设计更改的可行性。</li><li>监控 Rook 对 NFS 导出功能的支持情况，确保与 Ceph 的集成顺畅。</li></ul>",6)])])}const C=e(i,[["render",p]]);export{u as __pageData,C as default};
